B.P2=new A.aH("kanun_05",B.ch,"Manevi tazminat davalar\u0131nda verilen kararlar bak\u0131m\u0131ndan istinaf yolu nas\u0131ld\u0131r?",B.IB,1,"Manevi tazminat davalar\u0131nda dava de\u011feri/h\xfckmedilen miktar d\xfc\u015f\xfck olsa dahi, miktar g\xf6zetilmeksizin istinaf yolu a\xe7\u0131k kabul edilir (kesinlik s\u0131n\u0131r\u0131 manevi tazminat istemine uygulanmaz).")
B.IR=s(["Karar ge\xe7ersiz olur.","Karar \u015fekl\xee/maddi anlamda kesinle\u015fir ve icra edilebilir h\xe2le gelir.","Dava yeniden ilk derece mahkemesinde g\xf6r\xfcl\xfcr.","Karar resen Yarg\u0131tay\u2019a g\xf6nderilir."],t.s)
B.P5=new A.aH("kanun_06",B.ch,"S\xfcresinde kanun yoluna ba\u015fvurulmayan bir karar bak\u0131m\u0131ndan sonu\xe7 nedir?",B.IR,1,"Kanun yolu s\xfcresi i\xe7inde ba\u015fvurulmazsa veya kanun yolu kapal\u0131ysa karar kesinle\u015fir; kesinle\u015fen karar icra edilebilir ve kesin h\xfck\xfcm (res judicata) etkisi do\u011furur.")
